// Health is the resolver for the health field.
func (r *queryResolver) Health(ctx context.Context) (string, error) {
	if _, err := r.Queries.Ping(ctx); err != nil {
		return "", fmt.Errorf("DB に接続できません: %w", err)
	}
	return "ok", nil
}

